class Parser:
    def __init__(self, source):
        self.source = source
        self.all_tokens = lex(source)
        self.tokens = [t for t in self.all_tokens if t.kind not in ('WS', 'COMMENT')]
        self.pos = 0

    def peek(self, offset=0):
        if self.pos + offset < len(self.tokens):
            return self.tokens[self.pos + offset]
        return None

    def match(self, kind, value=None):
        tok = self.peek()
        if tok and tok.kind == kind:
            if value is None or tok.value == value:
                return tok
        return None

    def consume(self, kind=None, value=None):
        tok = self.peek()
        if tok:
            if kind and tok.kind != kind:
                raise ParseError(f"Expected {kind}, got {tok.kind}", tok.line, tok.col, tok.start_byte)
            if value and tok.value != value:
                raise ParseError(f"Expected {value}, got {tok.value}", tok.line, tok.col, tok.start_byte)
            self.pos += 1
            return tok
        raise ParseError("Unexpected EOF", 1, 1, len(self.source))

    def parse(self):
        if not self.tokens:
            raise ParseError("Unexpected EOF", 1, 1, 0)
        expr = self.parse_expr()
        if self.pos < len(self.tokens):
            tok = self.peek()
            raise ParseError(f"Unexpected token {tok.value}", tok.line, tok.col, tok.start_byte)
        return expr

    def parse_expr(self):
        tok = self.peek()
        if not tok:
            raise ParseError("Unexpected EOF", 1, 1, len(self.source))

        # Lambda or Let or If or With or Assert
        if tok.kind == 'KEYWORD':
            if tok.value == 'let':
                return self.parse_let()
            elif tok.value == 'if':
                return self.parse_if()
            elif tok.value == 'with':
                return self.parse_with()
            elif tok.value == 'assert':
                return self.parse_assert()

        # Check for Lambda: ident : expr, or { pattern } : expr, or pattern_bind : expr
        if self.is_lambda():
            return self.parse_lambda()

        return self.parse_op_expr(min_prec=1)

    def is_lambda(self):
        tok = self.peek()
        if not tok: return False
        # ident :
        if tok.kind == 'IDENT' and self.peek(1) and self.peek(1).kind == 'COLON':
            return True
        # { pattern } ... :
        if tok.kind == 'LBRACE':
            # Scan ahead to matching RBRACE and check if COLON or @ follows
            p = self.pos + 1
            depth = 1
            while p < len(self.tokens) and depth > 0:
                if self.tokens[p].kind == 'LBRACE': depth += 1
                elif self.tokens[p].kind == 'RBRACE': depth -= 1
                p += 1
            if depth == 0 and p < len(self.tokens):
                nxt = self.tokens[p]
                if nxt.kind == 'COLON': return True
                if nxt.kind == 'AT': return True
        # ident @ { ... } :
        if tok.kind == 'IDENT' and self.peek(1) and self.peek(1).kind == 'AT' and self.peek(2) and self.peek(2).kind == 'LBRACE':
            return True
        return False

    def parse_let(self):
        let_tok = self.consume('KEYWORD', 'let')
        # Check if legacy let: let { ... }
        if self.peek() and self.peek().kind == 'LBRACE':
            lbrace = self.consume('LBRACE')
            entries = self.parse_bindings_until('RBRACE')
            rbrace = self.consume('RBRACE')
            return LegacyLetExpr(entries, let_tok.start_byte, rbrace.end_byte, let_tok.line, let_tok.col)

        entries = self.parse_bindings_until('KEYWORD', 'in')
        in_tok = self.consume('KEYWORD', 'in')
        body = self.parse_expr()
        return LetInExpr(entries, body, let_tok.start_byte, body.end_byte, let_tok.line, let_tok.col)

    def parse_bindings_until(self, end_kind, end_value=None):
        entries = []
        while self.peek():
            tok = self.peek()
            if tok.kind == end_kind and (end_value is None or tok.value == end_value):
                break
            if tok.kind == 'KEYWORD' and tok.value == 'inherit':
                entries.append(self.parse_inherit())
            else:
                entries.append(self.parse_binding())
        return entries

    def parse_binding(self):
        path = self.parse_attr_path()
        eq_tok = self.consume('EQ')
        val = self.parse_expr()
        semi = self.consume('SEMICOLON')
        return Binding(path, val, path.start_byte, semi.end_byte, path.line, path.col)

    def parse_inherit(self):
        inh_tok = self.consume('KEYWORD', 'inherit')
        from_expr = None
        if self.peek() and self.peek().kind == 'LPAREN':
            self.consume('LPAREN')
            from_expr = self.parse_expr()
            self.consume('RPAREN')
        attrs = []
        while self.peek() and self.peek().kind not in ('SEMICOLON', 'KEYWORD', 'RBRACE'):
            tok = self.peek()
            if tok.kind == 'IDENT':
                attrs.append(Ident(tok.value, tok.start_byte, tok.end_byte, tok.line, tok.col))
                self.consume()
            elif tok.kind in ('STRING', 'IND_STRING'):
                attrs.append(StringLit(tok.value, [tok.value], tok.start_byte, tok.end_byte, tok.line, tok.col))
                self.consume()
            else:
                break
        semi = self.consume('SEMICOLON')
        return InheritStmt(from_expr, attrs, inh_tok.start_byte, semi.end_byte, inh_tok.line, inh_tok.col)

    def parse_if(self):
        if_tok = self.consume('KEYWORD', 'if')
        cond = self.parse_expr()
        self.consume('KEYWORD', 'then')
        then_e = self.parse_expr()
        self.consume('KEYWORD', 'else')
        else_e = self.parse_expr()
        return IfExpr(cond, then_e, else_e, if_tok.start_byte, else_e.end_byte, if_tok.line, if_tok.col)

    def parse_with(self):
        w_tok = self.consume('KEYWORD', 'with')
        env = self.parse_expr()
        self.consume('SEMICOLON')
        body = self.parse_expr()
        return WithExpr(env, body, w_tok.start_byte, body.end_byte, w_tok.line, w_tok.col)

    def parse_assert(self):
        a_tok = self.consume('KEYWORD', 'assert')
        cond = self.parse_expr()
        self.consume('SEMICOLON')
        body = self.parse_expr()
        return AssertExpr(cond, body, a_tok.start_byte, body.end_byte, a_tok.line, a_tok.col)

    def parse_lambda(self):
        tok = self.peek()
        arg = None
        start_byte = tok.start_byte
        line, col = tok.line, tok.col

        if tok.kind == 'IDENT':
            if self.peek(1) and self.peek(1).kind == 'COLON':
                ident_tok = self.consume('IDENT')
                arg = Ident(ident_tok.value, ident_tok.start_byte, ident_tok.end_byte, ident_tok.line, ident_tok.col)
                self.consume('COLON')
            elif self.peek(1) and self.peek(1).kind == 'AT':
                ident_tok = self.consume('IDENT')
                bind_ident = Ident(ident_tok.value, ident_tok.start_byte, ident_tok.end_byte, ident_tok.line, ident_tok.col)
                self.consume('AT')
                pattern = self.parse_pattern()
                arg = PatternBind(bind_ident, pattern, bind_first=True, start_byte=start_byte, end_byte=pattern.end_byte, line=line, col=col)
                self.consume('COLON')
        elif tok.kind == 'LBRACE':
            pattern = self.parse_pattern()
            if self.peek() and self.peek().kind == 'AT':
                self.consume('AT')
                ident_tok = self.consume('IDENT')
                bind_ident = Ident(ident_tok.value, ident_tok.start_byte, ident_tok.end_byte, ident_tok.line, ident_tok.col)
                arg = PatternBind(bind_ident, pattern, bind_first=False, start_byte=start_byte, end_byte=bind_ident.end_byte, line=line, col=col)
            else:
                arg = pattern
            self.consume('COLON')

        body = self.parse_expr()
        return LambdaExpr(arg, body, start_byte, body.end_byte, line, col)

    def parse_pattern(self):
        lbrace = self.consume('LBRACE')
        entries = []
        has_ellipsis = False

        while self.peek() and self.peek().kind != 'RBRACE':
            tok = self.peek()
            if tok.kind == 'ELLIPSIS':
                self.consume('ELLIPSIS')
                has_ellipsis = True
                break
            if tok.kind == 'IDENT':
                id_tok = self.consume('IDENT')
                ident_node = Ident(id_tok.value, id_tok.start_byte, id_tok.end_byte, id_tok.line, id_tok.col)
                default_expr = None
                if self.peek() and self.peek().kind == 'HAS': # ?
                    self.consume('HAS')
                    default_expr = self.parse_expr()
                entries.append((ident_node, default_expr))
                if self.peek() and self.peek().kind == 'COMMA':
                    self.consume('COMMA')
                else:
                    break
            else:
                break
        rbrace = self.consume('RBRACE')
        return Pattern(entries, has_ellipsis, lbrace.start_byte, rbrace.end_byte, lbrace.line, lbrace.col)

    def parse_op_expr(self, min_prec):
        # Operator precedence table
        # 1: -> (right)
        # 2: || (left)
        # 3: && (left)
        # 4: == != (non-assoc)
        # 5: < > <= >= (non-assoc)
        # 6: ? (non-assoc)
        # 7: // (right)
        # 8: + - (left)
        # 9: * / (left)
        # 10: ++ (right)
        # 11: unary ! -
        # 12: application
        # 13: select .

        left = self.parse_unary_or_app()

        PREC_TABLE = {
            'IMPL': (1, 'right'),
            'OR_LOGICAL': (2, 'left'),
            'AND': (3, 'left'),
            'EQ_EQ': (4, 'non'),
            'NEQ': (4, 'non'),
            'LT': (5, 'non'),
            'GT': (5, 'non'),
            'LE': (5, 'non'),
            'GE': (5, 'non'),
            'HAS': (6, 'non'),
            'UPDATE': (7, 'right'),
            'PLUS': (8, 'left'),
            'MINUS': (8, 'left'),
            'STAR': (9, 'left'),
            'SLASH': (9, 'left'),
            'CONCAT': (10, 'right'),
        }

        while True:
            tok = self.peek()
            if not tok or tok.kind not in PREC_TABLE:
                break
            prec, assoc = PREC_TABLE[tok.kind]
            if prec < min_prec:
                break

            op_tok = self.consume()
            if tok.kind == 'HAS':
                path = self.parse_attr_path()
                left = HasAttrExpr(left, path, left.start_byte, path.end_byte, left.line, left.col)
            else:
                next_min_prec = prec if assoc == 'right' else prec + 1
                right = self.parse_op_expr(next_min_prec)
                left = BinaryExpr(op_tok.value, left, right, left.start_byte, right.end_byte, left.line, left.col)

        return left

    def parse_unary_or_app(self):
        tok = self.peek()
        if tok and tok.kind in ('NOT', 'MINUS'):
            op_tok = self.consume()
            sub = self.parse_unary_or_app()
            return UnaryExpr(op_tok.value, sub, op_tok.start_byte, sub.end_byte, op_tok.line, op_tok.col)

        # Application
        fn = self.parse_select()
        while self.is_app_next():
            arg = self.parse_select()
            fn = ApplyExpr(fn, arg, fn.start_byte, arg.end_byte, fn.line, fn.col)
        return fn

    def is_app_next(self):
        tok = self.peek()
        if not tok: return False
        if tok.kind in ('IDENT', 'INT', 'FLOAT', 'BOOL', 'NULL', 'STRING', 'IND_STRING',
                        'URI', 'PATH', 'SEARCH_PATH', 'LBRACE', 'LBRACK', 'LPAREN'):
            return True
        if tok.kind == 'KEYWORD' and tok.value == 'rec':
            return True
        return False

    def parse_select(self):
        target = self.parse_primary()
        while self.peek() and self.peek().kind == 'DOT':
            self.consume('DOT')
            path = self.parse_attr_path()
            default_expr = None
            if self.peek() and self.peek().kind == 'KEYWORD' and self.peek().value == 'or':
                self.consume('KEYWORD', 'or')
                default_expr = self.parse_select() # or primary
            target = SelectExpr(target, path, default_expr, target.start_byte, (default_expr or path).end_byte, target.line, target.col)
            if default_expr:
                break
        return target

    def parse_attr_path(self):
        tok = self.peek()
        start_byte = tok.start_byte
        line, col = tok.line, tok.col
        parts = []

        while True:
            t = self.peek()
            if not t: break
            if t.kind == 'IDENT':
                id_t = self.consume('IDENT')
                parts.append(Ident(id_t.value, id_t.start_byte, id_t.end_byte, id_t.line, id_t.col))
            elif t.kind == 'KEYWORD':
                kw_t = self.consume('KEYWORD')
                parts.append(Ident(kw_t.value, kw_t.start_byte, kw_t.end_byte, kw_t.line, kw_t.col))
            elif t.kind in ('STRING', 'IND_STRING'):
                str_t = self.consume()
                parts.append(StringLit(str_t.value, [str_t.value], str_t.start_byte, str_t.end_byte, str_t.line, str_t.col))
            elif t.kind == 'LBRACE': # antiquoted attr in path ${expr}
                str_node = self.parse_primary()
                parts.append(str_node)
            else:
                break

            if self.peek() and self.peek().kind == 'DOT':
                # Check if next token after DOT is valid attr identifier/keyword/string
                next_t = self.peek(1)
                if next_t and next_t.kind in ('IDENT', 'KEYWORD', 'STRING', 'IND_STRING', 'LBRACE'):
                    self.consume('DOT')
                else:
                    break
            else:
                break

        end_byte = parts[-1].end_byte if parts else start_byte
        return AttrPath(parts, start_byte, end_byte, line, col)

    def parse_primary(self):
        tok = self.peek()
        if not tok:
            raise ParseError("Unexpected EOF", 1, 1, len(self.source))

        if tok.kind == 'IDENT':
            self.consume('IDENT')
            return Ident(tok.value, tok.start_byte, tok.end_byte, tok.line, tok.col)
        elif tok.kind == 'BOOL':
