        if tok.kind == 'KEYWORD':
            if tok.value == 'let':
                return self.parse_let()
            elif tok.value == 'if':
                return self.parse_if()
            elif tok.value == 'with':
                return self.parse_with()
            elif tok.value == 'assert':
                return self.parse_assert()

        # Check for Lambda: ident : expr, or { pattern } : expr, or pattern_bind : expr
        if self.is_lambda():
