import os
import tomli

class Config:
    def __init__(self, disabled=None, ignore=None):
        self.disabled = set(disabled or [])
        self.ignore = set(ignore or ['.direnv'])

def load_config(config_path):
    if not config_path:
        config_path = '.'

    target_file = config_path
    if os.path.isdir(config_path):
        target_file = os.path.join(config_path, 'statix.toml')

    if not os.path.isfile(target_file):
        return Config()

    try:
        with open(target_file, 'rb') as f:
            data = tomli.load(f)
        disabled = set(data.get('disabled', []))
        ignore = set(data.get('ignore', ['.direnv']))
        return Config(disabled=disabled, ignore=ignore)
    except Exception:
        return Config()

